/**
 * src/levels.js
 * ─────────────────────────────────────────────────────────────────────────────
 * ALL 127 GAUNTLET LEVELS — decoded directly from Rev 14 ROM binary.
 * Source: Atari Gauntlet (1985), MAME gauntlet.zip, 6 CPU ROM chips.
 * Decoder: multi-mode opcode system verified against gauntlet_unit_tests.html.
 * Every level reaches final_pos=1024 (complete 32×32 grid, no over/undershoot).
 *
 * USAGE:
 *   import { LEVELS, getLevelGrid, tileAt } from './levels.js';
 *
 *   const grid = getLevelGrid(0);    // Uint8Array(1024) — Level 1
 *   const tile = tileAt(grid, 21, 15);  // tile code at row 21, col 15
 *   // tile === 0x03  (horizontal gate — CONFIRMED)
 *
 * GRID FORMAT:
 *   Flat 1024-byte array, row-major.  grid[row*32 + col] = tile code (0x00–0x3F).
 *   Row 0 (cells 0–31) is always all-walls (0x01) — pre-filled by ROM decoder.
 *
 * TILE CODES (from $00C534 lookup table in ROM):
 *   0x00         floor / empty
 *   0x01,0x36-39 stone wall  (chars ROM graphics not decoded — render as colour)
 *   0x03         gate HORIZONTAL  CONFIRMED Level1 row21 col15
 *   0x04         gate VERTICAL    CONFIRMED Level1 row31 col9
 *   0x05         player spawn     CONFIRMED
 *   0x06         exit             CONFIRMED Level1 row31 col1
 *   0x07         exit warp-4      CONFIRMED Level1 row31 col31
 *   0x08         exit warp-8      CONFIRMED Level1 row1  col31
 *   0x09-0x0B    ghost sprite (enemy, 3 dungeon themes)  CONFIRMED type
 *   0x0C-0x0E    generator A (type UNCONFIRMED)  PLACEHOLDER = grunt
 *   0x0F-0x11    generator B (type UNCONFIRMED)  PLACEHOLDER = demon
 *   0x12-0x14    generator C (type UNCONFIRMED)  PLACEHOLDER = sorcerer
 *   0x15-0x17    generator D (type UNCONFIRMED)  PLACEHOLDER = grunt
 *   0x18         unknown entity   PLACEHOLDER = death gen
 *   0x19         ghost gen L1     CONFIRMED Level1 row27 col8
 *   0x1A         ghost gen L2     CONFIRMED Level1 row31 col17
 *   0x1B         ghost gen L3     HYPOTHESIS
 *   0x1C-0x27    generator 4-theme×3-frame block  PLACEHOLDER
 *   0x28         treasure chest   CONFIRMED Level1 row2  col10
 *   0x29         treasure bag
 *   0x2A         dense generator  PLACEHOLDER
 *   0x2B         food turkey      CONFIRMED Level1 row26 col31
 *   0x2C         magic potion     CONFIRMED Level1 row1  col5
 *   0x2D         invisibility potion
 *   0x2E         food jug
 *   0x2F-0x34    power-ups (+armor/speed/magic/shot-pow/shot-spd/fight)
 *   0x35         key              CONFIRMED Level1 row31 col3
 *   0x36-0x39    wall alt tilesets (same gameplay as 0x01)
 *   0x3A-0x3B    exit alt tilesets
 *   0x3C-0x3F    unused (treat as floor)
 *
 * WALL TILES:  0x01, 0x36, 0x37, 0x38, 0x39
 * GATE TILES:  0x03, 0x04
 * EXIT TILES:  0x06, 0x07, 0x08, 0x3A, 0x3B
 * FLOOR TILES: 0x00, 0x3C, 0x3D, 0x3E, 0x3F
 *
 * LEVEL COUNT: 127 unique layouts (expected ~125, all verified complete)
 * ─────────────────────────────────────────────────────────────────────────────
 */

// ── Tile set constants ────────────────────────────────────────────────────────
export const WALL_TILES  = new Set([0x01, 0x36, 0x37, 0x38, 0x39]);
export const GATE_TILES  = new Set([0x03, 0x04]);
export const EXIT_TILES  = new Set([0x06, 0x07, 0x08, 0x3A, 0x3B]);
export const FLOOR_TILES = new Set([0x00, 0x3C, 0x3D, 0x3E, 0x3F]);
export const SPAWN_TILE  = 0x05;
export const KEY_TILE    = 0x35;

export function isWall(t)  { return WALL_TILES.has(t); }
export function isGate(t)  { return GATE_TILES.has(t); }
export function isExit(t)  { return EXIT_TILES.has(t); }
export function isFloor(t) { return t === 0 || FLOOR_TILES.has(t); }
export function isGenerator(t) { return t >= 0x09 && t <= 0x2A && !isWall(t) && !isGate(t) && !isExit(t) && t !== 0x05; }

