/**
 * Get the decoded tile grid for a level (0-based index).
 * @param {number} levelIndex  0 = first ROM level
 * @returns {Uint8Array}  1024 bytes, grid[row*32+col] = tile code
 */
export function getLevelGrid(levelIndex) {
  if (levelIndex < 0 || levelIndex >= _GRIDS.length) {
    throw new RangeError(`Level ${levelIndex} out of range (0–${_GRIDS.length - 1})`);
  }
  const hex = _GRIDS[levelIndex];
  const out = new Uint8Array(1024);
  for (let i = 0; i < 1024; i++) {
    out[i] = parseInt(hex.slice(i*2, i*2+2), 16);
  }
  return out;
}

/**
 * Get the tile code at (row, col) in a level grid.
 * @param {Uint8Array} grid
 * @param {number} row  0–31
 * @param {number} col  0–31
 * @returns {number} tile code 0x00–0x3F
 */
export function tileAt(grid, row, col) {
  if (row < 0 || row > 31 || col < 0 || col > 31) return 0x01; // out of bounds = wall
  return grid[row * 32 + col];
}

/**
 * Find all tiles of a given code in a level grid.
 * @param {Uint8Array} grid
 * @param {number|number[]} tileCode  code or array of codes to find
 * @returns {Array<{row,col}>}
 */
export function findTiles(grid, tileCode) {
  const codes = Array.isArray(tileCode) ? new Set(tileCode) : new Set([tileCode]);
  const results = [];
  for (let i = 0; i < 1024; i++) {
    if (codes.has(grid[i])) results.push({ row: Math.floor(i/32), col: i%32 });
  }
  return results;
}

/**
 * Get spawn points for a level.
 * @param {Uint8Array} grid
 * @returns {Array<{row,col}>}
 */
export function getSpawns(grid) { return findTiles(grid, SPAWN_TILE); }

/**
 * Get exits for a level.
 * @param {Uint8Array} grid
 * @returns {Array<{row,col,tile}>}
 */
export function getExits(grid) {
  return [...EXIT_TILES].flatMap(t => findTiles(grid,t).map(p=>({...p,tile:t})));
}

/**
 * Get all gates (locked doors) in a level.
 * @param {Uint8Array} grid
 * @returns {Array<{row,col,horizontal}>}
 */
export function getGates(grid) {
  return [
    ...findTiles(grid, 0x03).map(p=>({...p, horizontal:true})),
    ...findTiles(grid, 0x04).map(p=>({...p, horizontal:false})),
  ];
}

/**
 * Total number of decoded levels.
 */
export const LEVEL_COUNT = _GRIDS.length;

/**
 * Pre-decoded all-levels array (lazy-loads on first access).
 * Use getLevelGrid(i) for on-demand loading instead.
 */
export const LEVELS = { get length() { return LEVEL_COUNT; } };
